    class UpgradeHandler extends RouterItemHandler {
        UpgradeHandler() {
            super(ModularRouterBlockEntity.COMPILE_UPGRADES, getUpgradeSlotCount(), s -> s.getItem() instanceof UpgradeItem);
        }

        @Override
        public boolean isItemValid(int slot, @Nonnull ItemStack stack) {
            // can't have the same upgrade in more than one slot
            for (int i = 0; i < getSlots(); i++) {
                if (slot != i && stack.getItem() == getStackInSlot(i).getItem()) return false;
            }
            return super.isItemValid(slot, stack);
        }

        @Override
        protected int getStackLimit(int slot, @Nonnull ItemStack stack) {
            if (!(stack.getItem() instanceof UpgradeItem)) return 0;
            return ((UpgradeItem) stack.getItem()).getStackLimit(slot);
        }
    }

    private record CompiledIndexedModule(CompiledModule compiledModule, int index) {
    }

    class RouterEnergyBuffer extends EnergyStorage {
        private int excess;  // "hidden" energy due to energy upgrades being removed

        public RouterEnergyBuffer(int capacity) {
            super(capacity);
            excess = 0;
        }

        @Override
        public boolean canExtract() {
            return super.canExtract() && getRedstoneBehaviour().shouldRun(getRedstonePower() > 0, false);
        }

        @Override
        public boolean canReceive() {
            return super.canReceive() && getRedstoneBehaviour().shouldRun(getRedstonePower() > 0, false);
        }

        @Override
        public int receiveEnergy(int maxReceive, boolean simulate) {
            int n = super.receiveEnergy(maxReceive, simulate);
            if (n != 0 && !simulate) setChanged();
            return n;
        }

        @Override
        public int extractEnergy(int maxExtract, boolean simulate) {
            int n = super.extractEnergy(maxExtract, simulate);
            if (n != 0 && !simulate) setChanged();
            return n;
        }

        void updateForEnergyUpgrades(int nEnergyUpgrades) {
            int oldCapacity = capacity;
            capacity = ConfigHolder.common.router.fePerEnergyUpgrade.get() * nEnergyUpgrades;
            if (energy > capacity) {
                // now not enough capacity - stow the excess energy
                excess += energy - capacity;
                energy = capacity;
            } else {
                // more capacity than energy - move what we can from excess to main storage
                int available = capacity - energy;
                int toMove = Math.min(available, excess);
                excess -= toMove;
                energy += toMove;
            }
            maxExtract = maxReceive = ConfigHolder.common.router.feXferPerEnergyUpgrade.get() * nEnergyUpgrades;
            if (oldCapacity == 0 && capacity != 0 || oldCapacity != 0 && capacity == 0) {
                // in case any pipes/cables need to connect/disconnect
                nonNullLevel().updateNeighborsAt(getBlockPos(), ModBlocks.MODULAR_ROUTER.get());
            }
        }

        public int getTransferRate() {
            return maxExtract;
        }

        @Override
        public Tag serializeNBT() {
            CompoundTag tag = new CompoundTag();
            if (energy > 0) tag.putInt("Energy", energy);
            if (capacity > 0) tag.putInt("Capacity", capacity);
            if (excess > 0) tag.putInt("Excess", excess);
            return tag;
        }

        @Override
        public void deserializeNBT(Tag nbt) {
            if (!(nbt instanceof CompoundTag compound)) {
                throw new IllegalArgumentException("Can not deserialize to an instance that isn't the default implementation");
            }
            energy = compound.getInt("Energy");
            capacity = compound.getInt("Capacity");
            excess = compound.getInt("Excess");
        }

        public int getCapacity() {
            return capacity;
        }

        void setEnergyStored(int energyStored) {
            // only called client side for gui sync purposes
            this.energy = Math.min(energyStored, capacity);
        }
    }

    public class TrackedEnergy implements ContainerData {
        @Override
        public int get(int idx) {
            int res = 0;
            if (idx == 0) {
                res = energyStorage.getEnergyStored() & 0x0000FFFF;
            } else if (idx == 1) {
                res = (energyStorage.getEnergyStored() & 0xFFFF0000) >> 16;
            }
            return res;
        }

        @Override
        public void set(int idx, int val) {
            if (val < 0) val += 65536;  // due to int->short conversion silliness in SWindowPropertyPacket
            if (idx == 0) {
                energyStorage.setEnergyStored(energyStorage.getEnergyStored() & 0xFFFF0000 | val);
            } else if (idx == 1) {
                energyStorage.setEnergyStored(energyStorage.getEnergyStored() & 0x0000FFFF | val << 16);
            }
        }

        @Override
        public int getCount() {
            return 2;
        }
    }
}

package me.desht.modularrouters.container;

import me.desht.modularrouters.block.tile.ModularRouterBlockEntity;
import me.desht.modularrouters.core.ModBlockEntities;
import me.desht.modularrouters.core.ModMenuTypes;
import me.desht.modularrouters.item.module.ModuleItem;
import me.desht.modularrouters.item.upgrade.UpgradeItem;
import net.minecraft.core.BlockPos;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.Slot;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.items.IItemHandler;
import net.minecraftforge.items.SlotItemHandler;

import static me.desht.modularrouters.container.Layout.SLOT_X_SPACING;
import static me.desht.modularrouters.container.Layout.SLOT_Y_SPACING;

public class RouterMenu extends AbstractMRContainerMenu {
    private static final int BUFFER_SLOT = 0;
    public static final int MODULE_SLOT_START = 1;
    public static final int MODULE_SLOT_END = 9;
    private static final int UPGRADE_SLOT_START = 10;
    private static final int UPGRADE_SLOT_END = 14;
    private static final int BUFFER_XPOS = 8;
    private static final int BUFFER_YPOS = 40;
    private static final int HOTBAR_XPOS = 8;
    private static final int HOTBAR_YPOS = 162;
    private static final int PLAYER_INVENTORY_XPOS = 8;
    private static final int PLAYER_INVENTORY_YPOS = 104;
    public static final int MODULE_XPOS = 8;
    private static final int MODULE_YPOS = 72;
    public static final int UPGRADE_XPOS = 80;
    private static final int UPGRADE_YPOS = 40;
    public static final int TE_FIRST_SLOT = 36;
    private static final int TE_LAST_SLOT = TE_FIRST_SLOT + UPGRADE_SLOT_END;

    private final ModularRouterBlockEntity router;
    public final ModularRouterBlockEntity.TrackedEnergy data;

    public RouterMenu(int windowId, Inventory invPlayer, FriendlyByteBuf extraData) {
        this(windowId, invPlayer, extraData.readBlockPos());
    }

    public RouterMenu(int windowId, Inventory invPlayer, BlockPos routerPos) {
        super(ModMenuTypes.ROUTER_MENU.get(), windowId);

        this.router = invPlayer.player.level().getBlockEntity(routerPos, ModBlockEntities.MODULAR_ROUTER.get())
                .orElseThrow(() -> new IllegalStateException("router missing at " + routerPos));

        data = router.trackedEnergy;

        // player's hotbar
        for (int x = 0; x < 9; x++) {
            addSlot(new Slot(invPlayer, x, HOTBAR_XPOS + SLOT_X_SPACING * x, HOTBAR_YPOS));
        }
        // player's main inventory
        for (int y = 0; y < 3; y++) {
            for (int x = 0; x < 9; x++) {
                int slotNumber = 9 + y * 9 + x;
                int xpos = PLAYER_INVENTORY_XPOS + x * SLOT_X_SPACING;
                int ypos = PLAYER_INVENTORY_YPOS + y * SLOT_Y_SPACING;
                addSlot(new Slot(invPlayer, slotNumber, xpos, ypos));
            }
        }

        // item router buffer
        addSlot(new SlotItemHandler(router.getBuffer(), BUFFER_SLOT, BUFFER_XPOS, BUFFER_YPOS));

        // item router modules
        for (int slot = 0; slot < router.getModuleSlotCount(); slot++) {
            addSlot(new InstalledModuleSlot(router.getModules(), slot, MODULE_XPOS + slot * SLOT_X_SPACING, MODULE_YPOS));
        }
        // item router upgrades
        for (int slot = 0; slot < router.getUpgradeSlotCount(); slot++) {
            addSlot(new SlotItemHandler(router.getUpgrades(), slot, UPGRADE_XPOS + slot * SLOT_X_SPACING, UPGRADE_YPOS));
        }

        addDataSlots(data);
    }

    @Override
    public boolean stillValid(Player player) {
        return !router.isRemoved() && Vec3.atCenterOf(router.getBlockPos()).distanceToSqr(player.position()) <= 64;
    }

    @Override
    public ItemStack quickMoveStack(Player player, int sourceSlotIndex) {
        Slot sourceSlot = slots.get(sourceSlotIndex);
        if (sourceSlot == null || !sourceSlot.hasItem()) {
            return ItemStack.EMPTY;
        }
        ItemStack sourceStack = sourceSlot.getItem();
        ItemStack copyOfSourceStack = sourceStack.copy();

        // Check if the slot clicked is one of the vanilla container slots
        if (sourceSlotIndex < TE_FIRST_SLOT) {
            // This is a vanilla container slot so merge the stack into the appropriate part of the router's inventory
            if (sourceStack.getItem() instanceof ModuleItem) {
                // shift-clicked a module: see if there's a free module slot
                if (!moveItemStackTo(sourceStack, TE_FIRST_SLOT + MODULE_SLOT_START, TE_FIRST_SLOT + MODULE_SLOT_END + 1, false)) {
                    return ItemStack.EMPTY;
                }
            } else if (sourceStack.getItem() instanceof UpgradeItem) {
                // shift-clicked an upgrade: see if there's a free upgrade slot
                if (!moveItemStackTo(sourceStack, TE_FIRST_SLOT + UPGRADE_SLOT_START, TE_FIRST_SLOT + UPGRADE_SLOT_END + 1, false)) {
                    return ItemStack.EMPTY;
                }
            } else {
                // try to merge item into the router's buffer slot
                if (!moveItemStackTo(sourceStack, TE_FIRST_SLOT + BUFFER_SLOT, TE_FIRST_SLOT + BUFFER_SLOT + 1, false)) {
                    return ItemStack.EMPTY;
                }
            }
        } else if (sourceSlotIndex < TE_FIRST_SLOT + TE_LAST_SLOT) {
            // This is a router slot, so merge the stack into the players inventory
            if (!moveItemStackTo(sourceStack, 0, TE_FIRST_SLOT - 1, false)) {
                return ItemStack.EMPTY;
            }
        } else {
            System.err.print("Invalid moduleSlotIndex: " + sourceSlotIndex);
            return ItemStack.EMPTY;
        }

        // If stack size == 0 (the entire stack was moved) set slot contents to null
        if (sourceStack.isEmpty()) {
            sourceSlot.set(ItemStack.EMPTY);
        } else {
            sourceSlot.setChanged();
        }

        sourceSlot.onTake(player, sourceStack);
        return copyOfSourceStack;
    }

    public ModularRouterBlockEntity getRouter() {
        return router;
    }

    public static class InstalledModuleSlot extends SlotItemHandler {
        // this is just so the slot can be easily identified for item tooltip purposes
        InstalledModuleSlot(IItemHandler itemHandler, int index, int xPosition, int yPosition) {
            super(itemHandler, index, xPosition, yPosition);
        }
    }
}

package me.desht.modularrouters.item;

import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.StringTag;
import net.minecraft.nbt.Tag;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;

import java.util.Objects;
import java.util.UUID;

public interface IPlayerOwned {
    String NBT_OWNER = "Owner";

    default String getOwnerName(ItemStack stack) {
        if (!stack.hasTag() || !Objects.requireNonNull(stack.getTag()).contains(NBT_OWNER)) return null;

        ListTag l = stack.getTag().getList(NBT_OWNER, Tag.TAG_STRING);
        return l.getString(0);
    }

    default UUID getOwnerID(ItemStack stack) {
        if (!stack.hasTag() || !Objects.requireNonNull(stack.getTag()).contains(NBT_OWNER)) return null;

        ListTag l = stack.getTag().getList(NBT_OWNER, Tag.TAG_STRING);
        return UUID.fromString(l.getString(1));
    }

    default void setOwner(ItemStack stack, Player player) {
        CompoundTag compound = stack.getOrCreateTag();
        ListTag owner = new ListTag();
        owner.add(StringTag.valueOf(player.getDisplayName().getString()));
        owner.add(StringTag.valueOf(player.getUUID().toString()));
        compound.put(NBT_OWNER, owner);
        stack.setTag(compound);
    }
}

package me.desht.modularrouters.item.module;

import me.desht.modularrouters.util.ModuleHelper;
import net.minecraft.world.item.ItemStack;

public interface IRangedModule {
    int getBaseRange();
    int getHardMaxRange();

    default int getCurrentRange(ItemStack stack) { // yay java 8
        return Math.max(1, Math.min(getHardMaxRange(), getBaseRange() + ModuleHelper.getRangeModifier(stack)));
    }

    default int getCurrentRange(int boost) { // yay java 8
        return Math.max(1, Math.min(getHardMaxRange(), getBaseRange() + boost));
    }
}

