package me.desht.modularrouters.logic;

import me.desht.modularrouters.client.util.ClientUtil;
import me.desht.modularrouters.util.MiscUtil;
import net.minecraft.ChatFormatting;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.GlobalPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraftforge.common.capabilities.ForgeCapabilities;
import net.minecraftforge.common.util.LazyOptional;
import net.minecraftforge.energy.IEnergyStorage;
import net.minecraftforge.items.IItemHandler;

import javax.annotation.Nullable;
import java.util.Objects;

/**
 * Represents the target for a given module, including the dimension, blockpos
 * and face of the block where insertion/extraction will occur.
 */
public class ModuleTarget {
    public final GlobalPos gPos;
    public final Direction face;
    public final String blockTranslationKey;

    private LazyOptional<IItemHandler> cachedItemCap = LazyOptional.empty();
    private LazyOptional<IEnergyStorage> cachedEnergyCap = LazyOptional.empty();

    public ModuleTarget(GlobalPos gPos, Direction face, String blockTranslationKey) {
        this.gPos = gPos;
        this.face = face;
        this.blockTranslationKey = blockTranslationKey;
    }

    public ModuleTarget(GlobalPos gPos, Direction face) {
        this(gPos, face, "");
    }

    public ModuleTarget(GlobalPos gPos) {
        this(gPos, null);
    }

    public CompoundTag toNBT() {
        CompoundTag ext = new CompoundTag();
        ext.put("Pos", MiscUtil.serializeGlobalPos(gPos));
        ext.putByte("Face", (byte) face.get3DDataValue());
        ext.putString("InvName", blockTranslationKey);
        return ext;
    }

    public static ModuleTarget fromNBT(CompoundTag nbt) {
        GlobalPos gPos = MiscUtil.deserializeGlobalPos(nbt.getCompound("Pos"));
        Direction face = Direction.from3DDataValue(nbt.getByte("Face"));
        return new ModuleTarget(gPos, face, nbt.getString("InvName"));
    }

    public boolean isSameWorld(@Nullable Level world) {
        return world != null && gPos.dimension() == world.dimension();
    }

    public boolean isSameWorld(ModuleTarget dst) {
        return gPos.dimension() == dst.gPos.dimension();
    }

    /**
     * Check for existence of an item handler client-side.  The target dimension must be the same as the client's
     * current dimension.
     *
     * @return a (lazy optional) item handler
     */
    public boolean hasItemHandlerClientSide() {
        Level w = ClientUtil.theClientWorld();
        return isSameWorld(w) && getItemHandlerFor(w).isPresent();
    }

    /**
     * Get an item handler for the module target.  Only call this server-side.
     *
     * @return a (lazy optional) item handler
     */
    public LazyOptional<IItemHandler> getItemHandler() {
        return getItemHandlerFor(MiscUtil.getWorldForGlobalPos(gPos));
    }

    private LazyOptional<IItemHandler> getItemHandlerFor(Level w) {
        // called both client and server side...
        if (!cachedItemCap.isPresent()) {
            BlockPos pos = gPos.pos();
            if (w == null || !w.isLoaded(pos)) {
                cachedItemCap = LazyOptional.empty();
            } else {
                BlockEntity te = w.getBlockEntity(pos);
                cachedItemCap = te == null ? LazyOptional.empty() : te.getCapability(ForgeCapabilities.ITEM_HANDLER, face);
            }
            if (cachedItemCap.isPresent()) cachedItemCap.addListener(c -> cachedItemCap = LazyOptional.empty());
        }
        return cachedItemCap;
    }

    /**
     * Try to get an energy handler for this module target.  Only call this server-side.
     *
     * @return a (lazy optional) energy handler
     */
    public LazyOptional<IEnergyStorage> getEnergyHandler() {
        if (!cachedEnergyCap.isPresent()) {
            BlockPos pos = gPos.pos();
            Level w = MiscUtil.getWorldForGlobalPos(gPos);
            if (w == null || !w.isLoaded(pos)) {
                cachedEnergyCap = LazyOptional.empty();
            } else {
                BlockEntity te = w.getBlockEntity(pos);
                cachedEnergyCap = te == null ? LazyOptional.empty() : te.getCapability(ForgeCapabilities.ENERGY, face);
            }
            if (cachedEnergyCap.isPresent()) cachedEnergyCap.addListener(c -> cachedEnergyCap = LazyOptional.empty());
        }
        return cachedEnergyCap;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof ModuleTarget that)) return false;
        return gPos.equals(that.gPos) && face == that.face;
    }

    @Override
    public int hashCode() {
        return Objects.hash(gPos, face);
    }

    @Override
    public String toString() {
        return MiscUtil.locToString(gPos) + " " + face;
    }

    public Component getTextComponent() {
        return Component.translatable(blockTranslationKey).withStyle(ChatFormatting.WHITE)
                .append(Component.literal(" @ " + this).withStyle(ChatFormatting.AQUA));
    }
}

package me.desht.modularrouters.logic.compiled;

import it.unimi.dsi.fastutil.objects.Object2IntOpenHashMap;
import me.desht.modularrouters.block.tile.ModularRouterBlockEntity;
import me.desht.modularrouters.core.ModItems;
import me.desht.modularrouters.item.augment.AugmentItem.AugmentCounter;
import me.desht.modularrouters.item.module.IRangedModule;
import me.desht.modularrouters.item.module.ModuleItem;
import me.desht.modularrouters.item.module.ModuleItem.RelativeDirection;
import me.desht.modularrouters.logic.ModuleTarget;
import me.desht.modularrouters.logic.RouterRedstoneBehaviour;
import me.desht.modularrouters.logic.filter.Filter;
import me.desht.modularrouters.util.BlockUtil;
import me.desht.modularrouters.util.CountedItemStacks;
import me.desht.modularrouters.util.MiscUtil;
import me.desht.modularrouters.util.ModuleHelper;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.GlobalPos;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.items.IItemHandler;
import net.minecraftforge.items.ItemHandlerHelper;
import org.apache.commons.lang3.Validate;

import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import java.util.Collections;
import java.util.List;
import java.util.Map;

public abstract class CompiledModule {
    private final Filter filter;
    private final ModuleItem module;
    private final RelativeDirection direction;
    private final List<ModuleTarget> targets;
    private final RouterRedstoneBehaviour behaviour;
    private final ModuleItem.Termination termination;
    private final Direction facing;
    private final Direction routerFacing;
    private final int regulationAmount;
    private final AugmentCounter augmentCounter;
    private final int range, rangeSquared;

    private int lastMatchPos = 0;
    private final Map<BlockPos,Integer> lastMatchPosMap = new Object2IntOpenHashMap<>();

    /**
     * Base constructor for compiled modules.  This can be called for both installed and uninstalled modules;
     * when the module is not installed in a router, null can be passed, so any subclass constructors must be able to
     * handle a null router.
     *
     * @param router router the module is installed in, may be null for an uninstalled module
     * @param stack item stack of the module item being compiled
     */
    CompiledModule(@Nullable ModularRouterBlockEntity router, ItemStack stack) {
        Validate.isTrue(stack.getItem() instanceof ModuleItem, "expected module item, got " + stack);

        module = (ModuleItem) stack.getItem();
        augmentCounter = new AugmentCounter(stack);
        direction = ModuleHelper.getRelativeDirection(stack);
        range = module instanceof IRangedModule ?
                ((IRangedModule) module).getCurrentRange(getRangeModifier()) : 0;
        rangeSquared = range * range;
        targets = setupTargets(router, stack);
        filter = new Filter(stack, shouldStoreRawFilterItems(), augmentCounter.getAugmentCount(ModItems.FILTER_ROUND_ROBIN_AUGMENT.get()) > 0);
        termination = ModuleHelper.getTermination(stack);
        behaviour = ModuleHelper.getRedstoneBehaviour(stack);
        regulationAmount = ModuleHelper.getRegulatorAmount(stack);
        facing = router == null ? null : router.getAbsoluteFacing(direction);
        routerFacing = router == null ? null : router.getAbsoluteFacing(RelativeDirection.FRONT);
    }

    /**
     * Execute this installed module.  When this is called, the router has already verified that the module has a
     * valid target, i.e. getTarget() will not return null.  This should only be called by the router.
     *
     * @param router router the module is installed in, may <strong>not</strong> be null
     * @return true if the module did some work, false otherwise
     */
    public abstract boolean execute(@Nonnull ModularRouterBlockEntity router);

    @Nonnull
    public Filter getFilter() {
        return filter;
    }

    public RelativeDirection getDirection() {
        return direction;
    }

    protected boolean shouldStoreRawFilterItems() {
        return false;
    }

    /**
     * Get the static target for a router module.  This is set up when the router is compiled, and does not
     * necessarily reflect the true target for all modules.  Use {@link #getEffectiveTarget(ModularRouterBlockEntity)}
     * to get the actual target that should be interacted with when executing the module.
     *
     * @return the first target as set up by {@link #setupTargets(ModularRouterBlockEntity, ItemStack)}
     */
    ModuleTarget getTarget() {
        return targets == null || targets.isEmpty() ? null : targets.get(0);
    }

    /**
     * Used by modules which can store multiple targets, e.g. the distributor module.  See also
     * {@link #getTarget()}.
     *
     * @return a list of the defined targets as set up by {@link #setupTargets(ModularRouterBlockEntity, ItemStack)}
     */
    List<ModuleTarget> getTargets() {
        return targets;
    }

    public boolean hasTarget() { return targets != null && !targets.isEmpty(); }

    public ModuleItem.Termination termination() {
        return termination;
    }

    RouterRedstoneBehaviour getRedstoneBehaviour() {
        return behaviour;
    }

    public int getRegulationAmount() {
        return augmentCounter.getAugmentCount(ModItems.REGULATOR_AUGMENT.get()) > 0 ? regulationAmount : 0;
    }

    int getAugmentCount(Item augmentType) {
        return augmentCounter.getAugmentCount(augmentType);
    }

    /**
     * Get the absolute direction this module faces, based on its relative direction and the facing of the router
     * in which it's installed.  This will be null if the module isn't installed in a router, or the router's facing
     * direction if the module's relative direction is NONE.
     *
     * @return absolute direction of the module
     */
    Direction getFacing() {
        return facing;
    }

    public void onCompiled(ModularRouterBlockEntity router) {
        if (behaviour == RouterRedstoneBehaviour.PULSE) {
            router.setHasPulsedModules(true);
        }
    }

    public void cleanup(ModularRouterBlockEntity router) {
        // does nothing by default
    }

    /**
     * Get the last position where we found a match.  Caching this can help reduce the amount of inventory searching
     * needed for some modules.
     *
     * @param offset offset from the last saved position
     * @param size size of the inventory being searched
     * @return the last position including offset, and wrapped to start of inventory if necessary
     */
    private int getLastMatchPos(BlockPos key, int offset, int size) {
        int pos = (key == null ? lastMatchPos : lastMatchPosMap.getOrDefault(key, 0)) + offset;
        while (pos >= size) pos -= size;
        return pos;
    }

    /**
     * Store the last position where we found a match.
     *
     * @param lastMatchPos last matched position
     */
    private void setLastMatchPos(BlockPos key, int lastMatchPos) {
        if (key == null)
            this.lastMatchPos = lastMatchPos;
        else
            lastMatchPosMap.put(key, lastMatchPos);
    }

    /**
     * Default target for this module is the block adjacent to the router, in the module's
     * configured direction.  Can be overridden by submodules.
     *
     * @param router router in which the module is installed
     * @param stack the module itemstack
     * @return a list of router target objects (for most modules this is a singleton list)
     */
    List<ModuleTarget> setupTargets(ModularRouterBlockEntity router, ItemStack stack) {
        if (router == null || (module.isDirectional() && direction == RelativeDirection.NONE)) {
            return null;
        }
        Direction facing = router.getAbsoluteFacing(direction);
        BlockPos pos = router.getBlockPos().relative(facing);
        String blockName = BlockUtil.getBlockName(router.getLevel(), pos);
        GlobalPos gPos = MiscUtil.makeGlobalPos(router.nonNullLevel(), pos);
        return Collections.singletonList(new ModuleTarget(gPos, facing.getOpposite(), blockName));
    }

    int getItemsPerTick(ModularRouterBlockEntity router) {
        int n = augmentCounter.getAugmentCount(ModItems.STACK_AUGMENT.get());
        return n > 0 ? Math.min(1 << n, 64) : router.getItemsPerTick();
    }

    /**
     * Try to transfer some items from the given ItemHandler to the given router.  The number of
     * items attempted depends on the router's stack upgrades.
     *
     * @param handler the item handler
     * @param key the handler's position, may be null - used as a key for search pos caching
     * @param router the router
     * @return items actually transferred
     */
    ItemStack transferToRouter(IItemHandler handler, @Nullable BlockPos key, ModularRouterBlockEntity router) {
        CountedItemStacks count = getRegulationAmount() > 0 ? new CountedItemStacks(handler) : null;

        ItemStack wanted = findItemToPull(router, handler, key, getItemsPerTick(router), count);
        if (wanted.isEmpty()) {
            return ItemStack.EMPTY;
        }

        ItemStack transferred = ItemStack.EMPTY;
        for (int i = 0; i < handler.getSlots(); i++) {
            int pos = getLastMatchPos(key, i, handler.getSlots());
            ItemStack toPull = handler.extractItem(pos, wanted.getCount(), true);
            if (toPull.isEmpty()) {
                // we'd found an item to pull but it looks like this handler doesn't allow us to extract it
                // give up, but advance the last match pos so we don't get stuck trying this slot forever
                setLastMatchPos(key, (pos + 1) % handler.getSlots());
                return transferred;
            }
            if (ItemHandlerHelper.canItemStacksStack(wanted, toPull)) {
                // this item is suitable for pulling
                ItemStack notInserted = router.insertBuffer(toPull);
                int inserted = toPull.getCount() - notInserted.getCount();
                transferred = handler.extractItem(pos, inserted, false);
                wanted.shrink(inserted);
                if (wanted.isEmpty() || router.isBufferFull()) {
                    setLastMatchPos(key, handler.getStackInSlot(pos).isEmpty() ? (pos + 1) % handler.getSlots() : pos);
                    return transferred;
                }
            }
        }
        return transferred;
    }

    private ItemStack findItemToPull(ModularRouterBlockEntity router, IItemHandler handler, BlockPos key, int nToTake, CountedItemStacks count) {
        ItemStack stackInRouter = router.peekBuffer(1);
        if (!stackInRouter.isEmpty() && getFilter().test(stackInRouter) && (count == null || count.getInt(stackInRouter) - nToTake >= getRegulationAmount())) {
            // something in the router - try to pull more of that
            return ItemHandlerHelper.copyStackWithSize(stackInRouter, nToTake);
        } else if (stackInRouter.isEmpty()) {
            // router empty - just pull the next item that passes the filter
            for (int i = 0; i < handler.getSlots(); i++) {
                int pos = getLastMatchPos(key, i, handler.getSlots());
                ItemStack stack = handler.getStackInSlot(pos);
                if (getFilter().test(stack) && (count == null || count.getInt(stack) - nToTake >= getRegulationAmount())) {
                    setLastMatchPos(key, pos);
                    return ItemHandlerHelper.copyStackWithSize(stack, nToTake);
                }
            }
        }
        return ItemStack.EMPTY;
    }

    /**
     * Get the effective target for this module, which is not necessarily the same as the result of getTarget().
     * E.g. for a Sender Mk1, the real target may be a few blocks away, and may change without router recompilation
     * if blocks are placed or removed.
     *
     * @return the real target for this module
     */
    public ModuleTarget getEffectiveTarget(ModularRouterBlockEntity router) {
        return getTarget();
    }

    public boolean shouldRun(boolean powered, boolean pulsed) {
        return getRedstoneBehaviour().shouldRun(powered, pulsed);
    }

    boolean isRegulationOK(ModularRouterBlockEntity router, boolean inbound) {
        if (regulationAmount == 0) return true; // no regulation
        int items = router.getBufferItemStack().getCount();
        return inbound && regulationAmount > items || !inbound && regulationAmount < items;
    }

    int getRange() {
        return range;
    }

    int getRangeSquared() {
        return rangeSquared;
    }

    private int getRangeModifier() {
        return getAugmentCount(ModItems.RANGE_UP_AUGMENT.get()) - getAugmentCount(ModItems.RANGE_DOWN_AUGMENT.get());
    }

    Direction getRouterFacing() {
        return routerFacing;
    }

    public void onNeighbourChange(ModularRouterBlockEntity router) {
    }

    public int getEnergyCost() {
        return module.getEnergyCost(ItemStack.EMPTY);
    }

    public boolean careAboutItemAttributes() {
        return false;
    }
}

package me.desht.modularrouters.logic.compiled;

import me.desht.modularrouters.block.tile.ModularRouterBlockEntity;
import me.desht.modularrouters.config.ConfigHolder;
import me.desht.modularrouters.core.ModItems;
import me.desht.modularrouters.logic.ModuleTarget;
import me.desht.modularrouters.util.BeamData;
import me.desht.modularrouters.util.BlockUtil;
import me.desht.modularrouters.util.InventoryUtils;
import me.desht.modularrouters.util.MiscUtil;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.GlobalPos;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraftforge.common.capabilities.ForgeCapabilities;
import net.minecraftforge.items.IItemHandler;
import net.minecraftforge.items.ItemHandlerHelper;

import javax.annotation.Nonnull;

public class CompiledSenderModule1 extends CompiledModule {
    public CompiledSenderModule1(ModularRouterBlockEntity router, ItemStack stack) {
        super(router, stack);
    }

    @Override
    public boolean execute(@Nonnull ModularRouterBlockEntity router) {
        IItemHandler buffer = router.getBuffer();
        ItemStack bufferStack = buffer.getStackInSlot(0);
        if (getFilter().test(bufferStack)) {
            PositionedItemHandler positionedItemHandler = findTargetInventory(router);
            if (positionedItemHandler.isValid()) {
                int nToSend = getItemsPerTick(router);
                if (getRegulationAmount() > 0) {
                    int existing = InventoryUtils.countItems(bufferStack, positionedItemHandler.handler, getRegulationAmount(), !getFilter().getFlags().isIgnoreDamage());
                    nToSend = Math.min(nToSend, getRegulationAmount() - existing);
                    if (nToSend <= 0) {
                        return false;
                    }
                }
                int sent = InventoryUtils.transferItems(buffer, positionedItemHandler.handler, 0, nToSend);
                if (sent > 0) {
                    if (ConfigHolder.common.module.senderParticles.get()) {
                        playParticles(router, positionedItemHandler.pos, ItemHandlerHelper.copyStackWithSize(bufferStack, sent));
                    }
                    return true;
                } else {
                    return false;
                }
            }
        }
        return false;
    }

    void playParticles(ModularRouterBlockEntity router, BlockPos targetPos, ItemStack stack) {
        if (router.getUpgradeCount(ModItems.MUFFLER_UPGRADE.get()) < 2) {
            router.addItemBeam(new BeamData(router.getTickRate(), targetPos, stack, getBeamColor()));
        }
    }

    protected int getBeamColor() {
        return 0xFFC000;
    }

    PositionedItemHandler findTargetInventory(ModularRouterBlockEntity router) {
        ModuleTarget target = getEffectiveTarget(router);
        if (target != null) {
            return target.getItemHandler().map(h -> new PositionedItemHandler(target.gPos.pos(), h)).orElse(PositionedItemHandler.INVALID);
        }
        return PositionedItemHandler.INVALID;
    }

    @Override
    public ModuleTarget getEffectiveTarget(ModularRouterBlockEntity router) {
        BlockPos p0 = getTarget().gPos.pos();
        BlockPos.MutableBlockPos pos = new BlockPos.MutableBlockPos(p0.getX(), p0.getY(), p0.getZ());
        Direction face = getTarget().face;
        Level level = router.nonNullLevel();
        for (int i = 1; i <= getRange(); i++) {
            BlockEntity te = level.getBlockEntity(pos);
            if (te != null && te.getCapability(ForgeCapabilities.ITEM_HANDLER, getTarget().face).isPresent()) {
                GlobalPos gPos = MiscUtil.makeGlobalPos(level, pos.immutable());
                return new ModuleTarget(gPos, face, BlockUtil.getBlockName(level, pos));
            } else if (!isPassable(level, pos, face)) {
                return null;
            }
            pos.move(getFacing());
        }
        return null;
    }

    private boolean isPassable(Level w, BlockPos pos, Direction face) {
        BlockState state = w.getBlockState(pos);
        return !MiscUtil.blockHasSolidSide(state, w, pos, face.getOpposite()) || !state.isSolidRender(w, pos);
    }

    record PositionedItemHandler(BlockPos pos, IItemHandler handler) {
        static final PositionedItemHandler INVALID = new PositionedItemHandler(null, null);

        boolean isValid() {
            return pos != null && handler != null;
        }
    }
}

package me.desht.modularrouters.logic.compiled;

import me.desht.modularrouters.block.tile.ModularRouterBlockEntity;
import me.desht.modularrouters.item.module.TargetedModule;
import me.desht.modularrouters.logic.ModuleTarget;
import net.minecraft.world.item.ItemStack;

import java.util.Collections;
import java.util.List;

public class CompiledSenderModule2 extends CompiledSenderModule1 {
    public CompiledSenderModule2(ModularRouterBlockEntity router, ItemStack stack) {
        super(router, stack);
    }

    @Override
    protected List<ModuleTarget> setupTargets(ModularRouterBlockEntity router, ItemStack stack) {
        return Collections.singletonList(TargetedModule.getTarget(stack, !router.nonNullLevel().isClientSide));
    }

    @Override
    protected PositionedItemHandler findTargetInventory(ModularRouterBlockEntity router) {
        ModuleTarget target = getEffectiveTarget(router);
        if (target == null || !validate(router, target)) {
            return PositionedItemHandler.INVALID;
        }

        return target.getItemHandler().map(h -> new PositionedItemHandler(target.gPos.pos(), h))
                .orElse(PositionedItemHandler.INVALID);
    }

    protected boolean validate(ModularRouterBlockEntity router, ModuleTarget target) {
        return target.isSameWorld(router.getLevel()) && router.getBlockPos().distSqr(target.gPos.pos()) <= getRangeSquared();
    }

    @Override
    protected int getBeamColor() {
        return 0xFF8000;
    }

    @Override
    public ModuleTarget getEffectiveTarget(ModularRouterBlockEntity router) {
        return getTarget();
    }
}

package me.desht.modularrouters.logic.compiled;

import me.desht.modularrouters.ModularRouters;
import me.desht.modularrouters.block.tile.ModularRouterBlockEntity;
import me.desht.modularrouters.core.ModItems;
import me.desht.modularrouters.item.module.ModuleItem;
import me.desht.modularrouters.logic.ModuleTarget;
import me.desht.modularrouters.util.BeamData;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.item.ItemStack;

public class CompiledSenderModule3 extends CompiledSenderModule2 {
    public CompiledSenderModule3(ModularRouterBlockEntity router, ItemStack stack) {
        super(router, stack);
    }

    @Override
    protected boolean validate(ModularRouterBlockEntity router, ModuleTarget target) {
        return target.isSameWorld(router.getLevel()) ||
                !ModularRouters.getDimensionBlacklist().test(target.gPos.dimension().location())
                        && !ModularRouters.getDimensionBlacklist().test(router.nonNullLevel().dimension().location());
    }

    @Override
    protected void playParticles(ModularRouterBlockEntity router, BlockPos targetPos, ItemStack stack) {
        if (router.getUpgradeCount(ModItems.MUFFLER_UPGRADE.get()) < 2) {
            Direction facing = router.getAbsoluteFacing(ModuleItem.RelativeDirection.FRONT);
            router.addItemBeam(new BeamData(router.getTickRate(), router.getBlockPos().relative(facing, 1), stack, 0x800080).fadeItems());
        }
    }
}

package me.desht.modularrouters.util;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.common.capabilities.ForgeCapabilities;
import net.minecraftforge.common.util.LazyOptional;
import net.minecraftforge.items.IItemHandler;
import net.minecraftforge.items.ItemHandlerHelper;

import javax.annotation.Nullable;
import java.util.Objects;
import java.util.Random;

public class InventoryUtils {
    /**
     * Drop all items from the given item handler into the world as item entities with random offsets & motions.
     *
     * @param world the world
     * @param pos blockpos to drop at (usually position of the item handler tile entity)
     * @param itemHandler the item handler
     */
    public static void dropInventoryItems(Level world, BlockPos pos, IItemHandler itemHandler) {
        Random random = new Random();
        for (int i = 0; i < itemHandler.getSlots(); i++) {
            ItemStack itemStack = itemHandler.getStackInSlot(i);
            if (!itemStack.isEmpty()) {
                float offsetX = random.nextFloat() * 0.8f + 0.1f;
                float offsetY = random.nextFloat() * 0.8f + 0.1f;
                float offsetZ = random.nextFloat() * 0.8f + 0.1f;
                while (!itemStack.isEmpty()) {
                    int stackSize = Math.min(itemStack.getCount(), random.nextInt(21) + 10);
                    ItemEntity entityitem = new ItemEntity(world, pos.getX() + (double) offsetX, pos.getY() + (double) offsetY, pos.getZ() + (double) offsetZ, new ItemStack(itemStack.getItem(), stackSize));
                    if (itemStack.hasTag()) {
                        entityitem.getItem().setTag(Objects.requireNonNull(itemStack.getTag()).copy());
                    }
                    itemStack.shrink(stackSize);

                    float motionScale = 0.05f;
                    entityitem.setDeltaMovement(random.nextGaussian() * (double) motionScale, random.nextGaussian() * (double) motionScale + 0.2, random.nextGaussian() * (double) motionScale);
                    world.addFreshEntity(entityitem);
                }
            }
        }
    }

    public static LazyOptional<IItemHandler> getInventory(Level world, BlockPos pos, @Nullable Direction side) {
        BlockEntity te = world.getBlockEntity(pos);
        return te == null ? LazyOptional.empty() : te.getCapability(ForgeCapabilities.ITEM_HANDLER, side);
    }

    /**
     * Transfer some items from the given slot in the given source item handler to the given destination handler.
     *
     * @param from source item handler
     * @param to destination item handler
     * @param slot slot in the source handler
     * @param count number of items to attempt to transfer
     * @return number of items actually transferred
     */
    public static int transferItems(IItemHandler from, IItemHandler to, int slot, int count) {
        if (from == null || to == null || count == 0) {
            return 0;
        }
        ItemStack toSend = from.extractItem(slot, count, true);
        if (toSend.isEmpty()) {
            return 0;
        }
        ItemStack excess = ItemHandlerHelper.insertItem(to, toSend, false);
        int inserted = toSend.getCount() - excess.getCount();
        from.extractItem(slot, inserted, false);
        return inserted;
    }

    /**
     * Drop an item stack into the world as an item entity.
     *
     * @param world the world
     * @param pos the block position (entity will spawn in centre of block pos)
     * @param stack itemstack to drop
     * @return true if the entity was spawned, false otherwise
     */
    public static boolean dropItems(Level world, Vec3 pos, ItemStack stack) {
        if (!world.isClientSide) {
            ItemEntity item = new ItemEntity(world, pos.x(), pos.y(), pos.z(), stack);
            return world.addFreshEntity(item);
        }
        return true;
    }

    /**
     * Get a count of the given item in the given item handler.  NBT data is not considered.
     *
     * @param toCount the item to count
     * @param handler the inventory to check
     * @param max maximum number of items to count
     * @param matchMeta whether to consider item metadata
     * @return number of items found, or the supplied max, whichever is smaller
     */
    public static int countItems(ItemStack toCount, IItemHandler handler, int max, boolean matchMeta) {
        int count = 0;
        for (int i = 0; i < handler.getSlots(); i++) {
            ItemStack stack = handler.getStackInSlot(i);
            if (!stack.isEmpty()) {
                boolean match;
                if (matchMeta) {
                    match = stack.is(toCount.getItem()) && (!stack.isDamageableItem() || stack.getDamageValue() == toCount.getDamageValue());
                } else {
                    match = stack.is(toCount.getItem());
                }
                if (match) {
                    count += stack.getCount();
                }
                if (count >= max) return max;
            }
        }
        return count;
    }
}

package me.desht.modularrouters.util;

import me.desht.modularrouters.ModularRouters;
import net.minecraft.ChatFormatting;
import net.minecraft.client.resources.language.I18n;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.GlobalPos;
import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.NbtUtils;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.resources.ResourceKey;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.tags.TagKey;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.BlockGetter;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.material.Fluid;
import net.minecraftforge.registries.ForgeRegistries;
import net.minecraftforge.server.ServerLifecycleHooks;

import javax.annotation.CheckForNull;
import java.text.NumberFormat;
import java.util.*;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

public class MiscUtil {
    public static final Direction[] DIRECTIONS = new Direction[] {
            // same as Direction.VALUES but that's private
            Direction.DOWN, Direction.UP, Direction.NORTH, Direction.SOUTH, Direction.WEST, Direction.EAST
    };

    private static final int WRAP_LENGTH = 45;

    public static void appendMultilineText(List<Component> result, ChatFormatting formatting, String key, Object... args) {
        for (String s : I18n.get(key, args).split(Pattern.quote("${br}"))) {
            result.add(Component.literal(s).withStyle(formatting));
        }
    }

    public static MutableComponent asFormattable(Component component) {
        return component instanceof MutableComponent ? (MutableComponent) component : component.plainCopy();
    }

    public static List<? extends Component> wrapStringAsTextComponent(String text) {
        return wrapString(text, WRAP_LENGTH).stream().map(Component::literal).toList();
    }

    public static String commify(int n) {
        return NumberFormat.getNumberInstance().format(n);
    }

    public static List<String> wrapString(String text, int maxCharPerLine) {
        List<String> result = new ArrayList<>();

        StringBuilder builder = new StringBuilder(text.length());
        String format = "";
        for (String para : text.split(Pattern.quote("${br}"))) {
            StringTokenizer tok = new StringTokenizer(para, " ");
            int lineLen = 0;
            while (tok.hasMoreTokens()) {
                String word = tok.nextToken();
                int idx = word.lastIndexOf("\u00a7");
                if (idx >= 0 && idx < word.length() - 1) {
                    // note the formatting sequence so we can apply to next line if any
                    format = word.substring(idx, idx + 2);
                    // formatting sequence does not contribute to line length
                    lineLen -= 2;
                }
                if (lineLen + word.length() > maxCharPerLine) {
                    result.add(builder.toString());
                    builder.delete(0, builder.length());
                    builder.append(format);
                    lineLen = 0;
                } else if (lineLen > 0) {
                    builder.append(" ");
                    lineLen++;
                }
                builder.append(word);
                lineLen += word.length();
            }
            result.add(builder.toString());
            builder.delete(0, builder.length());
            builder.append(format);
        }
        return result;
    }

    public static String locToString(ResourceLocation dim, BlockPos pos) {
        String s = dim.getNamespace().equals("minecraft") ? dim.getPath() : dim.toString();
        return String.format("%s [%d,%d,%d]", s, pos.getX(), pos.getY(), pos.getZ());
    }

    public static String locToString(GlobalPos pos) {
        return locToString(pos.dimension().location(), pos.pos());
    }

    public static ResourceLocation RL(String name) {
        return new ResourceLocation(ModularRouters.MODID, name);
    }

    public static int getYawFromFacing(Direction facing) {
        return switch (facing) {
            case NORTH -> 180;
            case WEST -> 90;
            case EAST -> -90;
            default -> 0; // including SOUTH
        };
    }

    public static Component settingsStr(String prefix, Component c) {
        return Component.literal(prefix).append(c);  // appendSibling
    }

    public static CompoundTag serializeGlobalPos(GlobalPos globalPos) {
        CompoundTag tag = new CompoundTag();
        tag.put("pos", net.minecraft.nbt.NbtUtils.writeBlockPos(globalPos.pos()));
        tag.putString("dim", globalPos.dimension().location().toString());
        return tag;
    }

    public static GlobalPos deserializeGlobalPos(CompoundTag tag) {
        ResourceKey<Level> worldKey = ResourceKey.create(Registries.DIMENSION, new ResourceLocation(tag.getString("dim")));
        return GlobalPos.of(worldKey, NbtUtils.readBlockPos(tag.getCompound("pos")));
    }

    @CheckForNull
    public static ServerLevel getWorldForGlobalPos(GlobalPos pos) {
        return ServerLifecycleHooks.getCurrentServer().getLevel(pos.dimension());
    }

    public static GlobalPos makeGlobalPos(Level w, BlockPos pos) {
        return GlobalPos.of(w.dimension(), pos);
    }

    // this method from Block went missing in 1.16.2
    public static boolean blockHasSolidSide(BlockState state, BlockGetter worldIn, BlockPos pos, Direction side) {
        return Block.isFaceFull(state.getBlockSupportShape(worldIn, pos), side);
    }

    public static Set<TagKey<Item>> itemTags(Item item) {
        //noinspection deprecation
        return ForgeRegistries.ITEMS.getHolder(item).orElseThrow().tags().collect(Collectors.toSet());
    }

    public static Set<TagKey<Fluid>> fluidTags(Fluid fluid) {
        return ForgeRegistries.FLUIDS.getHolder(fluid).orElseThrow().tags().collect(Collectors.toSet());
    }

    public static Optional<ResourceLocation> getRegistryName(Item item) {
        return Optional.ofNullable(ForgeRegistries.ITEMS.getKey(item));
    }

    public static Optional<ResourceLocation> getRegistryName(Block block) {
        return Optional.ofNullable(ForgeRegistries.BLOCKS.getKey(block));
    }

    public static boolean sameItemStackIgnoreDurability(ItemStack stack1, ItemStack stack2) {
        // disappeared from 1.19.2
        if (!stack1.isDamageableItem()) {
            return stack1.is(stack2.getItem());
        } else {
            return !stack2.isEmpty() && stack1.is(stack2.getItem());
        }
    }
}

package me.desht.modularrouters.util;

import me.desht.modularrouters.ModularRouters;
import me.desht.modularrouters.core.ModItems;
import me.desht.modularrouters.item.augment.AugmentItem;
import me.desht.modularrouters.item.module.ModuleItem;
import me.desht.modularrouters.item.module.ModuleItem.ModuleFlags;
import me.desht.modularrouters.item.module.ModuleItem.RelativeDirection;
import me.desht.modularrouters.item.module.ModuleItem.Termination;
import me.desht.modularrouters.logic.RouterRedstoneBehaviour;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.Tag;
import net.minecraft.world.item.ItemStack;

import javax.annotation.Nonnull;

/**
 * Collection of static convenience methods for managing NBT data in a module itemstack.
 */
public class ModuleHelper {
    public static final String NBT_DIRECTION = "Direction";
    public static final String NBT_REDSTONE_MODE = "RedstoneMode";
    public static final String NBT_REGULATOR_AMOUNT = "RegulatorAmount";
    public static final String NBT_FILTER = "ModuleFilter";
    public static final String NBT_AUGMENTS = "Augments";
    public static final String NBT_MATCH_ALL = "MatchAll";
    public static final String NBT_TERMINATION = "Termination";
    private static final String NBT_RR_COUNTER = "RoundRobinCounter";

    @Nonnull
    public static CompoundTag validateNBT(ItemStack stack) {
        return stack.hasTag() ? stack.getTag().getCompound(ModularRouters.MODID) : new CompoundTag();
    }

    @Nonnull
    public static CompoundTag validateNBTForWriting(ItemStack stack) {
        return stack.getOrCreateTagElement(ModularRouters.MODID);
    }

    public static boolean isBlacklist(ItemStack stack) {
        return checkFlag(stack, ModuleFlags.BLACKLIST);
    }

    public static boolean ignoreDamage(ItemStack stack) {
        return checkFlag(stack, ModuleFlags.IGNORE_DAMAGE);
    }

    public static boolean ignoreNBT(ItemStack stack) {
        return checkFlag(stack, ModuleFlags.IGNORE_NBT);
    }

    public static boolean ignoreTags(ItemStack stack) {
        return checkFlag(stack, ModuleFlags.IGNORE_TAGS);
    }

    public static boolean checkFlag(ItemStack stack, ModuleFlags flag) {
        CompoundTag tag = validateNBT(stack);
        return tag.contains(flag.getName(), Tag.TAG_BYTE) ? tag.getBoolean(flag.getName()) : flag.getDefaultValue();
    }

    public static Termination getTermination(ItemStack stack) {
        CompoundTag compound = validateNBT(stack);
        try {
            return compound.contains(ModuleHelper.NBT_TERMINATION, Tag.TAG_STRING) ?
                    Termination.valueOf(compound.getString(ModuleHelper.NBT_TERMINATION)) :
                    Termination.NONE;
        } catch (IllegalArgumentException e) {
            return Termination.NONE;
        }
    }

    public static RelativeDirection getRelativeDirection(ItemStack stack) {
        if (stack.getItem() instanceof ModuleItem m && m.isDirectional()) {
            CompoundTag compound = validateNBT(stack);
            try {
                String dirStr = compound.getString(NBT_DIRECTION);
                return dirStr.isEmpty() ? RelativeDirection.NONE : RelativeDirection.valueOf(dirStr);
            } catch (IllegalArgumentException e) {
                return RelativeDirection.NONE;
            }
        } else {
            return RelativeDirection.NONE;
        }
    }

    public static int getRegulatorAmount(ItemStack itemstack) {
        return validateNBT(itemstack).getInt(NBT_REGULATOR_AMOUNT);
    }

    public static RouterRedstoneBehaviour getRedstoneBehaviour(ItemStack stack) {
        AugmentItem.AugmentCounter counter = new AugmentItem.AugmentCounter(stack);
        if (counter.getAugmentCount(ModItems.REDSTONE_AUGMENT.get()) > 0) {
            CompoundTag compound = validateNBT(stack);
            try {
                return RouterRedstoneBehaviour.values()[compound.getByte(NBT_REDSTONE_MODE)];
            } catch (IllegalArgumentException | ArrayIndexOutOfBoundsException e) {
                return RouterRedstoneBehaviour.ALWAYS;
            }
        } else {
            return RouterRedstoneBehaviour.ALWAYS;
        }
    }

    public static int getRangeModifier(ItemStack stack) {
        AugmentItem.AugmentCounter counter = new AugmentItem.AugmentCounter(stack);
        return counter.getAugmentCount(ModItems.RANGE_UP_AUGMENT.get()) - counter.getAugmentCount(ModItems.RANGE_DOWN_AUGMENT.get());
    }

    public static boolean isMatchAll(ItemStack stack) {
        return validateNBT(stack).getBoolean(NBT_MATCH_ALL);
    }

    public static void setRoundRobinCounter(ItemStack moduleStack, int counter) {
        CompoundTag tag = validateNBTForWriting(moduleStack);
        tag.putInt(NBT_RR_COUNTER, counter);
    }

    public static int getRoundRobinCounter(ItemStack moduleStack) {
        return validateNBT(moduleStack).getInt(NBT_RR_COUNTER);
    }
}

package me.desht.modularrouters.util.fake_player;

import com.mojang.authlib.GameProfile;
import me.desht.modularrouters.block.tile.ModularRouterBlockEntity;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.entity.ExperienceOrb;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.common.util.FakePlayer;

public class RouterFakePlayer extends FakePlayer {
    private final ModularRouterBlockEntity router;
    private ItemStack prevHeldStack = ItemStack.EMPTY;

    public RouterFakePlayer(ModularRouterBlockEntity router, ServerLevel level, GameProfile profile) {
        super(level, profile);
        this.router = router;
    }

    @Override
    public Vec3 position() {
        return new Vec3(getX(), getY(), getZ());
    }

    @Override
    public boolean isSilent() {
        return true;
    }

    @Override
    public double getEyeY() {
        return getY();
    }

    @Override
    public void tick() {
        attackStrengthTicker++;
        if (router.caresAboutItemAttributes() && !ItemStack.matches(prevHeldStack, getMainHandItem())) {
            getAttributes().removeAttributeModifiers(prevHeldStack.getAttributeModifiers(EquipmentSlot.MAINHAND));
            getAttributes().addTransientAttributeModifiers(getMainHandItem().getAttributeModifiers(EquipmentSlot.MAINHAND));
            prevHeldStack = getMainHandItem().copy();
        }
    }


    @Override
    public void giveExperiencePoints(int amount) {
        Vec3 pos = Vec3.atCenterOf(router.getBlockPos().above());
        ExperienceOrb orb = new ExperienceOrb(router.nonNullLevel(), pos.x, pos.y, pos.z, amount);
        router.nonNullLevel().addFreshEntity(orb);
    }
}
